import{_ as r}from"./chunks/4.BHUw47UR.js";import{_ as i}from"./chunks/image2.DiCSfv3Q.js";import{_ as o}from"./chunks/image1.BEPpsZFs.js";import{_ as n,a as s}from"./chunks/image.DnKwf-A0.js";import{_ as l}from"./chunks/image4.AvWkE8iq.js";import{_ as c}from"./chunks/image.BfjhyjBp.js";import{_ as d}from"./chunks/image2.Q-khKGRV.js";import{_ as h}from"./chunks/image.BZc8PBVN.js";import{_ as p}from"./chunks/100.DMbJtyMU.js";import{_ as g}from"./chunks/community.BdKwbEUF.js";import{_ as m,C as u,o as b,c as _,ak as t,E as f}from"./chunks/framework.sbZkgmEx.js";const w="/projects/AiBlock/en/advanced-kit/assets/1.DZHNn-zM.webp",y="/projects/AiBlock/en/advanced-kit/assets/4.CA2vnNfK.webp",v="/projects/AiBlock/en/advanced-kit/assets/2.DUIn9PDd.webp",W=JSON.parse('{"title":"3.4 Beckoning Cat Arm","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Creative Builds/3.4 Beckoning Cat Arm.md","filePath":"docs/3.Creative Builds/3.4 Beckoning Cat Arm.md"}'),k={name:"docs/3.Creative Builds/3.4 Beckoning Cat Arm.md"};function x(P,e,q,C,A,j){const a=u("Pdf");return b(),_("div",null,[e[0]||(e[0]=t('<h1 id="_3-4-beckoning-cat-arm" tabindex="-1">3.4 Beckoning Cat Arm <a class="header-anchor" href="#_3-4-beckoning-cat-arm" aria-label="Permalink to &quot;3.4 Beckoning Cat Arm&quot;">​</a></h1><h2 id="_3-4-1-lesson-introduction" tabindex="-1">3.4.1 Lesson Introduction <a class="header-anchor" href="#_3-4-1-lesson-introduction" aria-label="Permalink to &quot;3.4.1 Lesson Introduction&quot;">​</a></h2><p>This lesson takes inspiration from the traditional beckoning cat to construct an interactive waving robotic arm. It explores the three fundamental programming structures: sequence, loop, and branch. Learners master servo angle control and ultrasonic distance measurement principles, completing two-stage tasks covering basic waving and automatic waving upon approach. Integrating servos with ultrasonic sensing organizes program architecture, establishes distance-sensing control logic, and prepares for advanced mechanical programming.</p><img loading="lazy" height="1662" width="1662" src="'+r+'" class="common_img" style="width:400px;"><h2 id="_3-4-2-learning-objectives" tabindex="-1">3.4.2 Learning Objectives <a class="header-anchor" href="#_3-4-2-learning-objectives" aria-label="Permalink to &quot;3.4.2 Learning Objectives&quot;">​</a></h2><ol><li><p><strong>Knowledge Objectives</strong>: Distinguish between sequence, loop, and branch program structures. Master servo control across 0° to 180°. Understand ultrasonic ranging principles. Grasp basic variable arithmetic operations.</p></li><li><p><strong>Skill Objectives</strong>: Wire the servo and ultrasonic sensor properly. Complete mounting and mechanical zero-point calibration for the arm. Program cyclical waving motions. Read ultrasonic detection distances accurately.</p></li><li><p><strong>Thinking Objectives</strong>: Build structured programming thinking. Combine three core control structures flexibly. Form closed-loop thinking for sensor-based control. Cultivate engineering habits of parameter calibration and iterative debugging.</p></li><li><p><strong>Application Objectives</strong>: Connect ultrasonic technology with real-world applications like automatic doors and sensor faucets. Understand distance sensing in daily life to inspire creative ideas for smart sensor systems.</p></li></ol><h2 id="_3-4-3-preparation" tabindex="-1">3.4.3 Preparation <a class="header-anchor" href="#_3-4-3-preparation" aria-label="Permalink to &quot;3.4.3 Preparation&quot;">​</a></h2><h3 id="_1-hardware-preparation" tabindex="-1">(1) Hardware Preparation <a class="header-anchor" href="#_1-hardware-preparation" aria-label="Permalink to &quot;(1) Hardware Preparation&quot;">​</a></h3><ul><li><p>AiBlock controller</p></li><li><p>180° block servo</p></li><li><p>Ultrasonic sensor</p></li><li><p>Building block parts pack</p></li><li><p>Type-C data cable</p></li><li><p>Assembly manual</p></li><li><p>Computer</p></li></ul><h3 id="_2-software-preparation" tabindex="-1">(2) Software Preparation <a class="header-anchor" href="#_2-software-preparation" aria-label="Permalink to &quot;(2) Software Preparation&quot;">​</a></h3><ul><li>WonderLab Graphical Programming Platform</li></ul><h2 id="_3-4-4-hands-on-project" tabindex="-1">3.4.4 Hands-On Project <a class="header-anchor" href="#_3-4-4-hands-on-project" aria-label="Permalink to &quot;3.4.4 Hands-On Project&quot;">​</a></h2><h3 id="_1-project-analysis" tabindex="-1">(1) Project Analysis <a class="header-anchor" href="#_1-project-analysis" aria-label="Permalink to &quot;(1) Project Analysis&quot;">​</a></h3><p>The core project for this lesson is an intelligent beckoning cat arm, realizing an interactive response that waves when someone approaches and stops when they leave. The ultrasonic sensor detects distance as the perception layer, while the servo oscillates the arm between 60° and 120° to create a waving motion as the execution layer. The program adopts a nested &quot;loop and branch&quot; structure: the loop continuously samples distance, and the branch checks whether the distance is under 25 cm to trigger waving, while keeping the arm stationary otherwise. This project also demonstrates the three fundamental programming structures: sequence within the waving cycle, loop for continuous execution, and branch for distance evaluation.</p><h3 id="_2-assembly-guide" tabindex="-1">(2) Assembly Guide <a class="header-anchor" href="#_2-assembly-guide" aria-label="Permalink to &quot;(2) Assembly Guide&quot;">​</a></h3>',15)),f(a,{src:"../../_static/shared/pdf/chapter_3/4.pdf"}),e[1]||(e[1]=t('<h3 id="_3-hardware-wiring" tabindex="-1">(3) Hardware Wiring <a class="header-anchor" href="#_3-hardware-wiring" aria-label="Permalink to &quot;(3) Hardware Wiring&quot;">​</a></h3><ul><li><p>Connect the 180° block servo to port <strong>S1</strong> of the controller using a 3-pin servo cable.</p></li><li><p>Connect the ultrasonic sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</p></li></ul><img loading="lazy" height="1101" width="1412" src="'+w+'" class="common_img" style="width:500px;"><h3 id="_4-adding-extensions" tabindex="-1">(4) Adding Extensions <a class="header-anchor" href="#_4-adding-extensions" aria-label="Permalink to &quot;(4) Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Ultrasonic sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+i+'" class="common_img" style="width:800px;"><ul><li>Select <strong>180° servo</strong> under the <strong>Motion module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+o+'" class="common_img" style="width:800px;"><h3 id="_5-core-blocks" tabindex="-1">(5) Core Blocks <a class="header-anchor" href="#_5-core-blocks" aria-label="Permalink to &quot;(5) Core Blocks&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Block</th><th style="text-align:center;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="257" width="228" src="'+n+'"></td><td style="text-align:center;"><img loading="lazy" height="70" width="108" src="'+s+'"></td><td style="text-align:left;">Compares two values and returns a true or false result</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="65" width="625" src="'+l+'"></td><td style="text-align:center;"><img loading="lazy" height="95" width="108" src="'+c+'"></td><td style="text-align:left;">Rotates the specified servo to a target angle at a set speed</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="48" width="304" src="'+d+'"></td><td style="text-align:center;"><img loading="lazy" height="80" width="99" src="'+h+'"></td><td style="text-align:left;">Obtains the obstacle distance detected by the ultrasonic sensor</td></tr></tbody></table><h3 id="_6-program-description-and-upload" tabindex="-1">(6) Program Description and Upload <a class="header-anchor" href="#_6-program-description-and-upload" aria-label="Permalink to &quot;(6) Program Description and Upload&quot;">​</a></h3><ul><li>Program Schematic</li></ul><img loading="lazy" height="361" width="430" src="'+y+'" class="common_img" style="width:400px;"><ul><li><p>Complete Program</p><p>After powering on, the program initializes the ultrasonic sensor on port A, then runs in a continuous loop. Inside the loop, it monitors obstacle distance in real time: when the measured distance is less than 25 cm, servo S1 rotates without delay to 120° at 40% speed, waits 0.5 s, then rotates without delay back to 60° at 40% speed, waits another 0.5 s, and returns to the loop for repeated monitoring.</p></li></ul><img loading="lazy" height="456" width="671" src="'+v+'" class="common_img" style="width:500px;"><ul><li><p>Program Upload</p><p>Following the animation, click <strong>Connect device</strong>, select the serial port, then click the upload button to upload the program to the controller and test the execution results.</p></li></ul><img loading="lazy" height="360" width="640" src="'+p+'" class="common_img" style="width:800px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1xyD_-3msc3KcaGQHLqkcPOZNSNXFIirT?usp=sharing" target="_blank" rel="noreferrer">Program Files</a>.</strong></p></div><h2 id="_3-4-5-expansion-and-challenge" tabindex="-1">3.4.5 Expansion and Challenge <a class="header-anchor" href="#_3-4-5-expansion-and-challenge" aria-label="Permalink to &quot;3.4.5 Expansion and Challenge&quot;">​</a></h2><p><strong>Project 1: Distance-Responsive Interactive Beckoning Cat</strong></p><p>Design multi-tiered proximity reactions: stay still when objects are far away at distances greater than 50 cm, wave slowly at medium range between 25 cm and 50 cm, and wave rapidly while illuminating RGB lights at close range under 25 cm. Implement multi-branch conditional logic to match different reactions to different distances, simulating an authentic greeting experience where closer visitors receive warmer welcomes. Practice multi-branch programming and parameter linkage.</p><p><strong>Project 2: Audiovisual Welcoming Cat Arm</strong></p><p>Incorporate buzzer sound effects and lighting: upon detecting an approaching visitor, the arm waves while playing a welcoming chime and flashing ultrasonic RGB lights. Designing a &quot;ding-dong&quot; doorbell melody coupled with waving motion creates a comprehensive smart greeter build. Practice multi-actuator coordination programming to understand system design where a single trigger initiates multiple responses.</p><h2 id="_3-4-6-q-a" tabindex="-1">3.4.6 Q&amp;A <a class="header-anchor" href="#_3-4-6-q-a" aria-label="Permalink to &quot;3.4.6 Q&amp;A&quot;">​</a></h2><p><strong>Question 1: Which sensor detects approaching objects? How does it determine distance?</strong></p><p>Answer: An ultrasonic sensor measures object distance. Its principle mirrors bat echolocation: the transmitter emits high-frequency sound waves inaudible to human ears. These waves travel forward, bounce off obstacles, and reflect back to the receiver. The sensor calculates distance by multiplying half the elapsed transit time by the speed of sound, approximately 340 m/s. Objects closer return echoes faster, while objects farther away return echoes slower. Ultrasonic ranging operates independently of ambient light, functioning reliably in complete darkness, and sees widespread use in automatic doors, reversing radar, and obstacle-avoidance robots.</p><p><strong>Question 2: What are the three fundamental structures of a program? What are their characteristics?</strong></p><p>Answer: Programs consist of three core structures, which combine to construct complex software. First is the <strong>sequence structure</strong>, where instructions execute strictly top-to-bottom one after another, serving as the simplest linear pattern like following step-by-step assembly instructions. Second is the <strong>loop structure</strong>, which repeats code segments continuously using repeat blocks, suited for persistent tasks like polling sensor values. Third is the <strong>branch structure</strong>, which directs execution along alternative paths based on conditional criteria using if-then blocks, providing decision-making capabilities. Combining these three structures enables developing versatile intelligent programs.</p><h2 id="_3-4-7-technical-support-and-product-discussion" tabindex="-1">3.4.7 Technical Support and Product Discussion <a class="header-anchor" href="#_3-4-7-technical-support-and-product-discussion" aria-label="Permalink to &quot;3.4.7 Technical Support and Product Discussion&quot;">​</a></h2><p>To share creative ideas and projects after exploring this kit, visit the Hiwonder Community:</p><a href="https://forum.hiwonder.com/" target="_blank" rel="noopener noreferrer"><img loading="lazy" height="640" width="1136" src="'+g+'" class="common_img" style="width:800px;"></a>',31))])}const G=m(k,[["render",x]]);export{W as __pageData,G as default};
